export default function problemLogConfirmed({
  spreadsheetId,
  updatedRange,
  updatedRows,
  updatedColumns,
  updatedCells,
  tableRange,
}) {
  if (
    typeof spreadsheetId !== "string" ||
    !spreadsheetId ||
    typeof updatedRange !== "string" ||
    !updatedRange ||
    updatedRows !== 1 ||
    updatedColumns !== 4 ||
    updatedCells !== 4 ||
    typeof tableRange !== "string"
  )
    throw new Error("Google Sheets did not confirm one complete problem row");
  return {
    log: { spreadsheetId, updatedRange, updatedRows, updatedColumns, updatedCells, tableRange },
  };
}

